import java.util.*;

class Vehicle {
    private final String licensePlate;
    Vehicle(String licensePlate) { this.licensePlate = licensePlate; }
    String getLicensePlate() { return licensePlate; }
}

class ParkingSlot {
    private final int slotNumber;
    private Vehicle parkedVehicle;
    ParkingSlot(int slotNumber) { this.slotNumber = slotNumber; }
    boolean isFree() { return parkedVehicle == null; }
    void park(Vehicle vehicle) { this.parkedVehicle = vehicle; }
    int getSlotNumber() { return slotNumber; }
}

class ParkingLot {
    private final List<ParkingSlot> slots = new ArrayList<>();
    ParkingLot(int totalSlots) {
        for (int i = 1; i <= totalSlots; i++) slots.add(new ParkingSlot(i));
    }
    Optional<ParkingSlot> parkVehicle(Vehicle vehicle) {
        for (ParkingSlot slot : slots) {
            if (slot.isFree()) {
                slot.park(vehicle);
                return Optional.of(slot);
            }
        }
        return Optional.empty();
    }
}

public class ParkingLotDemo {
    public static void main(String[] args) {
        ParkingLot lot = new ParkingLot(2);

        Vehicle car1 = new Vehicle("MH12AB1234");
        Vehicle car2 = new Vehicle("MH12CD5678");
        Vehicle car3 = new Vehicle("MH12EF9999");

        lot.parkVehicle(car1).ifPresent(slot ->
            System.out.println(car1.getLicensePlate() + " parked in slot " + slot.getSlotNumber()));

        lot.parkVehicle(car2).ifPresent(slot ->
            System.out.println(car2.getLicensePlate() + " parked in slot " + slot.getSlotNumber()));

        boolean thirdParked = lot.parkVehicle(car3).isPresent();
        System.out.println(car3.getLicensePlate() + " parked: " + thirdParked);
    }
}

