class Vehicle:
    def __init__(self, license_plate):
        self.license_plate = license_plate

    def get_license_plate(self):
        return self.license_plate


class ParkingSlot:
    def __init__(self, slot_number):
        self.slot_number = slot_number
        self.parked_vehicle = None

    def is_free(self):
        return self.parked_vehicle is None

    def park(self, vehicle):
        self.parked_vehicle = vehicle

    def get_slot_number(self):
        return self.slot_number


class ParkingLot:
    def __init__(self, total_slots):
        self.slots = [ParkingSlot(i) for i in range(1, total_slots + 1)]

    def park_vehicle(self, vehicle):
        for slot in self.slots:
            if slot.is_free():
                slot.park(vehicle)
                return slot
        return None


if __name__ == "__main__":
    lot = ParkingLot(2)

    car1 = Vehicle("MH12AB1234")
    car2 = Vehicle("MH12CD5678")
    car3 = Vehicle("MH12EF9999")

    slot1 = lot.park_vehicle(car1)
    if slot1:
        print(f"{car1.get_license_plate()} parked in slot {slot1.get_slot_number()}")

    slot2 = lot.park_vehicle(car2)
    if slot2:
        print(f"{car2.get_license_plate()} parked in slot {slot2.get_slot_number()}")

    third_parked = lot.park_vehicle(car3) is not None
    print(f"{car3.get_license_plate()} parked: {str(third_parked).lower()}")

