#include <bits/stdc++.h>
using namespace std;

class Vehicle {
    string licensePlate;
public:
    Vehicle(string licensePlate) : licensePlate(licensePlate) {}
    string getLicensePlate() { return licensePlate; }
};

class ParkingSlot {
    int slotNumber;
    Vehicle* parkedVehicle = nullptr;
public:
    ParkingSlot(int slotNumber) : slotNumber(slotNumber) {}
    bool isFree() { return parkedVehicle == nullptr; }
    void park(Vehicle* vehicle) { parkedVehicle = vehicle; }
    int getSlotNumber() { return slotNumber; }
};

class ParkingLot {
    vector<ParkingSlot> slots;
public:
    ParkingLot(int totalSlots) {
        for (int i = 1; i <= totalSlots; i++) slots.emplace_back(i);
    }

    ParkingSlot* parkVehicle(Vehicle* vehicle) {
        for (auto& slot : slots) {
            if (slot.isFree()) {
                slot.park(vehicle);
                return &slot;
            }
        }
        return nullptr;
    }
};

int main() {
    ParkingLot lot(2);

    Vehicle car1("MH12AB1234");
    Vehicle car2("MH12CD5678");
    Vehicle car3("MH12EF9999");

    ParkingSlot* slot1 = lot.parkVehicle(&car1);
    if (slot1) {
        cout << car1.getLicensePlate() << " parked in slot " << slot1->getSlotNumber() << endl;
    }

    ParkingSlot* slot2 = lot.parkVehicle(&car2);
    if (slot2) {
        cout << car2.getLicensePlate() << " parked in slot " << slot2->getSlotNumber() << endl;
    }

    bool thirdParked = lot.parkVehicle(&car3) != nullptr;
    cout << car3.getLicensePlate() << " parked: " << (thirdParked ? "true" : "false") << endl;

    return 0;
}
